// ── Donut morado/verde (mockup LOGRO2) ────────────────────────────────────
const DONUT_SIZE = 200;
const STROKE_WIDTH = 18;

function DonutChart({ percentage }) {
  const radius = (DONUT_SIZE - STROKE_WIDTH) / 2;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (percentage / 100) * circumference;

  return (
    <View style={donut.root}>
      <Svg width={DONUT_SIZE} height={DONUT_SIZE}>
        {/* Fondo morado (resto que falta) */}
        <Circle
          cx={DONUT_SIZE / 2}
          cy={DONUT_SIZE / 2}
          r={radius}
          stroke={colors.purple}
          strokeWidth={STROKE_WIDTH}
          fill="transparent"
        />
        {/* Aciertos verdes */}
        <Circle
          cx={DONUT_SIZE / 2}
          cy={DONUT_SIZE / 2}
          r={radius}
          stroke={colors.statGreen}
          strokeWidth={STROKE_WIDTH}
          fill="transparent"
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          strokeLinecap="round"
          transform={`rotate(-90 ${DONUT_SIZE / 2} ${DONUT_SIZE / 2})`}
        />
      </Svg>
      <View style={donut.label}>
        <Text style={donut.percentage}>
          {percentage}<Text style={donut.percentSign}>%</Text>
        </Text>
      </View>
    </View>
  );
}

const donut = StyleSheet.create({
  root: {
    width: DONUT_SIZE,
    height: DONUT_SIZE,
    alignItems: 'center',
    justifyContent: 'center',
  },
  label: {
    position: 'absolute',
    alignItems: 'center',
  },
  percentage: {
    fontSize: 58,
    fontFamily: 'Poppins-SemiBold',
    color: colors.textDark,
    letterSpacing: -1,
  },
  percentSign: {
    fontSize: 30,
    fontFamily: 'Poppins-SemiBold',
    color: colors.textDark,
  },
});

// ── Screen ───────────────────────────────────────────────────
export default function TrainingResultScreen({ navigation, route }) {
  const {
    answers = MOCK_DATA.answers,
    questions = MOCK_DATA.questions,
    source = MOCK_DATA.source,
    elapsedSeconds = MOCK_DATA.elapsedSeconds,
    challengeId = null,
    clanId = null,
    taskId = null,
  } = route?.params ?? {};

  const total = questions.length;
  const correct = answers.filter(a => a.isCorrect).length;
  const incorrect = total - correct;
  const percentage = total > 0 ? Math.round((correct / total) * 100) : 0;
  const isHighScore = percentage >= 90;
  const needsLab = incorrect > 0;

  // Persiste el intento en el backend UNA SOLA VEZ al montar. Sin esto el
  // Laboratorio de Errores no tiene con qué calcular los patrones de fallo.
  const [boeUnread, setBoeUnread] = React.useState(0);

  const savedRef = useRef(false);
  useEffect(() => {
    if (savedRef.current) return;
    savedRef.current = true;
    // Comprobar si hay cambios BOE pendientes para mostrar el hint
    boeApi.getFeed().then(res => {
        if (!res?.error && (res?.data?.totalUnread ?? 0) > 0) {
            setBoeUnread(res.data.totalUnread);
        }
    }).catch(() => {});
    const responses = buildResponses(questions, answers);
    if (responses.length === 0) return; // MOCK data, no persistimos
    // 'photo' no es un enum válido del backend — se guarda como 'generator'.
    const backendSource = source === 'photo' ? 'generator' : source;
    trainingApi
      .saveAttempt({
        source: backendSource,
        durationSecs: elapsedSeconds,
        responses,
      })
      .catch(() => { /* no bloqueamos la UI si falla */ });

    // Si venimos de un reto de clan y superamos el umbral del 60%, completamos el reto.
    if (challengeId && clanId && percentage >= 60) {
      motivationApi.completeChallenge(clanId, challengeId).catch(() => { });
    }

    // Si el test se lanzó desde una tarea de planificación, la marcamos como
    // completada para que suba el % del día y dispare la racha del bloque 4.
    if (taskId) {
      planningApi.toggleTask(taskId, true).catch(() => { });
    }
  }, []);

  const formatTime = (s) => {
    const m = Math.floor(s / 60).toString().padStart(2, '0');
    const sec = (s % 60).toString().padStart(2, '0');
    return `${m}:${sec}`;
  };

  // ── Pantalla de felicitación (≥90%) — mockup LOGRO ──
  if (isHighScore) {
    return (
      <SafeAreaView style={styles.root} edges={['top', 'bottom']}>
        <ScreenHeader title="Test completado" onBack={() => navigation.goBack()} />

        <ScrollView contentContainerStyle={styles.celebrationBody} showsVerticalScrollIndicator={false}>
          <View style={styles.trophyWrap}>
            <TrophyIllustration />
          </View>

          <Text style={styles.congrats}>¡FELICIDADES!</Text>
          <Text style={styles.congratsSub}>
            Estás de racha, has superado este test con un{' '}
            <Text style={{ fontFamily: 'Poppins-SemiBold', color: colors.textDark }}>{percentage}%</Text>
            {' '}de aciertos. ¿Qué quieres hacer ahora?
          </Text>

          <TouchableOpacity
            style={styles.primaryBtn}
            onPress={() => navigation.goBack()}
            activeOpacity={0.85}
          >
            <Text style={styles.primaryBtnText}>¿Vamos a por otro test?</Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={styles.ghostLink}
            onPress={() => navigation.navigate('Dashboard')}
            activeOpacity={0.7}
          >
            <Text style={styles.ghostLinkText}>Por hoy es suficiente, gracias</Text>
          </TouchableOpacity>
        </ScrollView>
      </SafeAreaView>
    );
  }

  // ── Pantalla de resultados con donut y estadísticas — mockup LOGRO2 ──
  return (
    <SafeAreaView style={styles.root} edges={['top', 'bottom']}>
      <ScreenHeader title="Test completado" onBack={() => navigation.goBack()} />

      <ScrollView
        contentContainerStyle={styles.contentPad}
        showsVerticalScrollIndicator={false}
      >
        <View style={styles.donutRow}>
          <DonutChart percentage={percentage} />
          <Text style={styles.correctCount}>{correct} de {total} correctas</Text>
        </View>

        <View style={styles.statsRow}>
          <View style={styles.statBox}>
            <Text style={[styles.statValue, { color: colors.statGreen }]}>{correct}</Text>
            <Text style={styles.statLabel}>Aciertos</Text>
          </View>
          <View style={styles.statBox}>
            <Text style={[styles.statValue, { color: colors.statRed }]}>{incorrect}</Text>
            <Text style={styles.statLabel}>Fallos</Text>
          </View>
          <View style={styles.statBox}>
            <Text style={[styles.statValue, { color: colors.textDark }]}>{formatTime(elapsedSeconds)}</Text>
            <Text style={styles.statLabel}>Tiempo</Text>
          </View>
        </View>

        {needsLab && (
          <View style={styles.errorChipWrap}>
            <View style={styles.errorChipPointer} />
            <View style={styles.errorChip}>
              <Text style={styles.chipTitle}>{incorrect} fallos detectados</Text>
              <Text style={styles.chipSub}>¡Refuérzalos con un test quirúrgico!</Text>
            </View>
          </View>
        )}

        {boeUnread > 0 && (
          <TouchableOpacity
            style={styles.boeHintCard}
            onPress={() => navigation.navigate('BoeHome')}
            activeOpacity={0.8}
            accessibilityLabel="Ver cambios BOE pendientes"
          >
            <View style={styles.boeHintDot} />
            <Text style={styles.boeHintText} numberOfLines={2}>
              {boeUnread === 1
                ? '1 cambio legislativo sin revisar en tu temario'
                : `${boeUnread} cambios legislativos sin revisar en tu temario`}
            </Text>
            <Text style={styles.boeHintCta}>Revisar →</Text>
          </TouchableOpacity>
        )}

        <Text style={styles.whatNow}>¿Qué quieres hacer ahora?</Text>

        {needsLab && (
          <TouchableOpacity
            style={styles.primaryBtn}
            onPress={() => {
              const incorrectQuestions = questions.filter((_, i) =>
                answers[i] && !answers[i].isCorrect
              );
              navigation.navigate('ErrorLab', { incorrectQuestions });
            }}
            activeOpacity={0.85}
          >
            <Text style={styles.primaryBtnText}>Ir al laboratorio de errores</Text>
          </TouchableOpacity>
        )}

        <TouchableOpacity
          style={styles.primaryBtn}
          onPress={() => navigation.navigate('Dashboard')}
          activeOpacity={0.85}
        >
          <Text style={styles.primaryBtnText}>Volver al inicio</Text>
        </TouchableOpacity>
      </ScrollView>
    </SafeAreaView>
  );
}

